resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then REGISTRATION_DATE end) as REGISTRATION_DATE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CLAIM_REFERENCE_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIM_REFERENCE_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CLAIM_REFERENCE_NUMBER end)) as CLAIM_REFERENCE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIM_REMARKS end) as CLAIM_REMARKS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CLAIM_STATUS end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIM_STATUS end)) as CLAIM_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NOTIFICATION_DATE end) as NOTIFICATION_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NET_INCURRED_AMOUNT end) as NET_INCURRED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GROSS_INCURRED_AMOUNT end) as GROSS_INCURRED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIM_TYPE end) as CLAIM_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIM_SUB_STATUS end) as CLAIM_SUB_STATUS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CLOSED_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLOSED_DATE end)) as CLOSED_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIM_CATEGORY end) as CLAIM_CATEGORY,
        max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_REFERENCE end) as POLICY_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LOSS_DATE end) as LOSS_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when REGISTRATION_DATE is not null or CLAIM_REFERENCE_NUMBER is not null or CLAIM_REMARKS is not null or CLAIM_STATUS is not null or NOTIFICATION_DATE is not null or NET_INCURRED_AMOUNT is not null or GROSS_INCURRED_AMOUNT is not null or CLAIM_TYPE is not null or CLAIM_SUB_STATUS is not null or CLOSED_DATE is not null or CLAIM_CATEGORY is not null or POLICY_REFERENCE is not null or LOSS_DATE is not null
                     then md5(upper(coalesce(cast(REGISTRATION_DATE as varchar), '') || '|' || coalesce(cast(CLAIM_REFERENCE_NUMBER as varchar), '') || '|' || coalesce(cast(CLAIM_REMARKS as varchar), '') || '|' || coalesce(cast(CLAIM_STATUS as varchar), '') || '|' || coalesce(cast(NOTIFICATION_DATE as varchar), '') || '|' || coalesce(cast(NET_INCURRED_AMOUNT as varchar), '') || '|' || coalesce(cast(GROSS_INCURRED_AMOUNT as varchar), '') || '|' || coalesce(cast(CLAIM_TYPE as varchar), '') || '|' || coalesce(cast(CLAIM_SUB_STATUS as varchar), '') || '|' || coalesce(cast(CLOSED_DATE as varchar), '') || '|' || coalesce(cast(CLAIM_CATEGORY as varchar), '') || '|' || coalesce(cast(POLICY_REFERENCE as varchar), '') || '|' || coalesce(cast(LOSS_DATE as varchar), '')))
                end as SAT_CLAIM_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_HEADER_HASHDIFF is not null
